import{z as i,x as s,o as E,c as d,q as o,j as A,D as e,d as r,s as B,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"样本外协议","description":"","frontmatter":{"title":"样本外协议","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/slm-oos-protocol.md","filePath":"quant/slm-oos-protocol.md","lastUpdated":1791063341000}'),p={name:"quant/slm-oos-protocol.md"};function m(u,a,D,c,f,h){const l=s("Mermaid");return E(),d("div",null,[a[2]||(a[2]=o('<h1 id="样本外协议" tabindex="-1">样本外协议 <a class="header-anchor" href="#样本外协议" aria-label="Permalink to &quot;样本外协议&quot;">​</a></h1><div class="epigraph"><p>「样本外」不是一个数据片段，是一个承诺：这段数据在你做完所有决定之前，谁都不许看。</p><footer>—— 据 Cawley and Talbot, *JMLR*, 2010；López de Prado, *Advances in Financial Machine Learning*, Wiley, 2018 整理</footer></div><p><a href="/quant/slm-overfitting-market">上一课</a>把过拟合分成泄漏、选择、环境三类，并指出修复只能来自协议。本课把协议写成可执行的时间表：数据怎么切、选择发生在哪、测试块何时动用、上线后谁接管。切分四参数（块、清洗、路径、聚合）的机械细节在<a href="/quant/fml-tscv-deep">时序交叉验证的深化</a>已收；本课管协议的政治学——每一个自由度归谁，何时关闭。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「留一部分数据做样本外」一句话里藏着至少四个自由度：怎么切、谁参与选择、切几次、什么时候算结束。每个自由度都可以被有意或无意地用来把测试块变成训练的一部分：在滚动结果上挑最好的窗口、看到测试段不行就回去换特征、影子盘不佳就改判据再跑一次。每一步局部都「合理」，合起来样本外就不存在了。缺口是把协议写成事先冻结的合同，让「样本外」这个词保持定义。</p><p><span class="marginnote">直觉类比：样本外协议像考前把试卷封存——不是不信任谁，而是试卷一旦开封，「第一次考」就再也立不住。看一眼测试块、不行再回去改特征，等于考砸后偷改答案重考，成绩单上每个数都跟着作废。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>五步合同。第一步切分：按时间切训练、验证、测试三段，接缝处 purge 清标签重叠、embargo 清特征最长滞后——机械沿<a href="/quant/fml-tscv-deep">时序交叉验证的深化</a>。第二步隔离：所有选择——模型族、\\(\\lambda\\)、深度、特征列、标签参数、评估口径——只许看训练与验证块，内外分工即<a href="/quant/nested-cv">嵌套交叉验证</a>的合同。第三步一次性：测试块只动用一次，第二次动用它就是新的样本内。第四步影子盘：上线前先只记录不建仓，对照<a href="/quant/live-drift-monitor">实盘漂移监测</a>预指定的统计量。第五步台账：每次尝试与每次协议修订都计入 \\(N\\)（<a href="/quant/fml-model-selection-protocol">模型选择协议</a>的五要素）。滚动重训下的同型合同是 walk-forward（<a href="/quant/walk-forward">样本外与滚动检验</a>），注意在其结果上挑窗口等于把检验段作废。</p><p><span class="marginnote">术语翻译：purge 是在切缝处删掉标签与另一侧重叠的样本——标签是未来 21 天收益，最后 21 天的行就得挪走；embargo 是再空出一段等于特征最长滞后的缓冲，防止信息从训练侧渗过去。两者都在修误差项，不是仪式。</span></p>',9)),(E(),A(n,null,{default:e(()=>[B(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%AE%AD%E7%BB%83%E5%9D%97%EF%BC%9A%E6%8B%9F%E5%90%88%22%5D%20--%3E%20B%5B%22purge%20%E4%B8%8E%20embargo%22%5D%0A%20%20B%20--%3E%20C%5B%22%E9%AA%8C%E8%AF%81%E5%9D%97%EF%BC%9A%E5%85%A8%E9%83%A8%E9%80%89%E6%8B%A9%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%B5%8B%E8%AF%95%E5%9D%97%EF%BC%9A%E5%8F%AA%E7%A2%B0%E4%B8%80%E6%AC%A1%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%BD%B1%E5%AD%90%E7%9B%98%EF%BC%9A%E5%8F%AA%E8%AE%B0%E5%BD%95%E4%B8%8D%E5%BB%BA%E4%BB%93%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%AE%9E%E7%9B%98%EF%BC%9A%E6%BC%82%E7%A7%BB%E7%9B%91%E6%B5%8B%E6%8E%A5%E7%AE%A1%22%5D%0A%20%20L%5B%22N%20%E5%8F%B0%E8%B4%A6%22%5D%20--%3E%20C%0A%20%20L%20--%3E%20E%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"为什么必须是时间外：截面相关与非平稳下，随机折把未来收益放进训练集，分数度量的是「见过的未来」；purge 对齐上一课的 \\(T/H\\) 账，embargo 对齐特征最长滞后，两者都不是仪式而是误差项的修正。为什么测试块只能用一次：每多用一次，报告的就是候选最大值而不是期望绩效，统计上回到选择类过拟合——Cawley-Talbot 指出用同一测试折反复评估的方差本身就是过拟合的指纹。协议不是道德要求，是让数字保持自称的含义：同一个 \\(0.4\\%\\) 的 \\(R^2\\)，在协议内是技能的量级，在协议外什么都不是。",-1)),(E(),A(n,null,{default:e(()=>[B(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20DATA%5B%22%E6%97%B6%E9%97%B4%E5%BA%8F%E5%88%97%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20RND%5B%22%E9%9A%8F%E6%9C%BA%E6%8A%98%EF%BC%9A%E6%8C%89%E6%A0%B7%E6%9C%AC%E9%9A%8F%E6%9C%BA%E5%88%86%22%5D%0A%20%20RND%20--%3E%20LEAK%5B%22%E6%9C%AA%E6%9D%A5%E6%94%B6%E7%9B%8A%E8%BF%9B%E5%85%A5%E8%AE%AD%E7%BB%83%E9%9B%86%22%5D%0A%20%20LEAK%20--%3E%20FAKE%5B%22%E5%88%86%E6%95%B0%E5%90%AB%E4%B9%89%EF%BC%9A%E8%A7%81%E8%BF%87%E6%9C%AA%E6%9D%A5%E5%90%8E%E7%9A%84%E5%A4%8D%E8%BF%B0%22%5D%0A%20%20DATA%20--%3E%20BLK%5B%22%E6%97%B6%E9%97%B4%E5%9D%97%EF%BC%9A%E6%8C%89%E5%B9%B4%E4%BB%BD%E5%88%87%22%5D%0A%20%20BLK%20--%3E%20PE%5B%22purge%20%E6%B8%85%E9%87%8D%E5%8F%A0%E5%8A%A0%20embargo%20%E6%B8%85%E6%BB%9E%E5%90%8E%22%5D%0A%20%20PE%20--%3E%20TRUE%5B%22%E5%88%86%E6%95%B0%E5%90%AB%E4%B9%89%EF%BC%9A%E7%9C%9F%E6%AD%A3%E7%9A%84%E6%A0%B7%E6%9C%AC%E5%A4%96%E4%BC%B0%E8%AE%A1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">数字实例：对毫无技能的策略把测试块动用 20 次，报告的是 20 个纯噪声结果里的最大值——它几乎必然「看起来不错」，正如抛 20 次硬币几乎必然出现一次连赢四五个。报最大值而不报期望，数字就退回选择类过拟合。</span></p><p><span class="marginnote">Gu-Kelly-Xiu（2020）的统一样本外设计：训练从样本起点起步、窗口逐年向前扩展、末段留作统一测试。统一协议的价值一半在诚实，一半在可比：各报各的最高分没有排名可言，同一时间背上同一检验才有。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>协议本身可被过拟合：试了三种切分挑最好的一种，选择只是换了个位置，台账照记；预注册的窄网格可以豁免嵌套，豁免的理由必须先写（<a href="/quant/nested-cv">嵌套交叉验证</a>的口径）。协议通过不证明因果也不保证未来，它只保证一件事：这个数字是它自称的那个估计量。环境类风险不归协议管——上线之后的衰减与漂移由监测接管，协议与监测的交接点就是影子盘。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>协议四自由度：怎么切、谁选择、切几次、何时结束；每个都要事先冻结。</li><li>时间块加 purge/embargo 是误差修正，不是仪式；随机折在市场数据上度量未来泄漏。</li><li>测试块一次性；影子盘只记录不建仓；每次尝试与修订都进 \\(N\\) 台账。</li><li>协议可被过拟合：挑切分、挑窗口都算试验；预注册例外要事先写明。</li><li>出处：Cawley and Talbot, <em>JMLR</em>, 2010；López de Prado, <em>Advances in Financial Machine Learning</em>, Wiley, 2018；Gu, Kelly and Xiu, <em>RFS</em>, 2020。</li></ul>',6))])}const _=i(p,[["render",m]]);export{F as __pageData,_ as default};
